 public class ProgressRing : FrameworkElement {
  public double Progress;public bool Paused,Resting;
  protected override void OnRender(DrawingContext dc) {base.OnRender(dc);double r=Math.Min(ActualWidth,ActualHeight)/2-9;var c=new Point(ActualWidth/2,ActualHeight/2);dc.DrawEllipse(null,new Pen(UI.Brush("Soft"),7),c,r,r);double p=Math.Max(0,Math.Min(.999999,Progress));if(p<=0)return;double a=p*Math.PI*2;var geom=new StreamGeometry();using(var ctx=geom.Open()){ctx.BeginFigure(new Point(c.X,c.Y-r),false,false);ctx.ArcTo(new Point(c.X+Math.Sin(a)*r,c.Y-Math.Cos(a)*r),new Size(r,r),0,p>.5,SweepDirection.Clockwise,true,false);}var pen=new Pen(UI.Brush(Paused?"Muted":Resting?"Green":"Accent"),7){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round};dc.DrawGeometry(null,pen,geom);}
 }
