  string previewTaskId;readonly Dictionary<string,Border> taskCards=new Dictionary<string,Border>();
  public Todo PreviewedTask {get{return app.Data.Tasks.FirstOrDefault(t=>t.Id==previewTaskId)??app.Engine.Current;}}
  public void PreviewTask(Todo task){previewTaskId=task==null?null:task.Id;RefreshTimer();}
  public void ClearTaskPreview(){previewTaskId=null;RefreshTimer();}
  void TogglePreview(){var task=PreviewedTask;if(task!=null&&task.IsGroup){app.StartTask(task);return;}if(task!=null&&(task.Done||task.Archived))return;if(task!=null&&(app.Data.Active==null||app.Data.Active.TaskId!=task.Id))app.StartTask(task);else app.ToggleTimer();}
  public void RefreshTimer() {
